WITH warehouse_stats AS ( SELECT cr.cr_warehouse_sk AS warehouse_sk, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_return_ship_cost) AS total_ship_cost, SUM(cr.cr_return_quantity) AS total_return_quantity, AVG(cr.cr_return_amount) AS avg_return_amount, COUNT(DISTINCT cr.cr_returning_addr_sk) AS distinct_returning_addr_cnt FROM catalog_returns cr GROUP BY cr.cr_warehouse_sk ), quantity_bins AS ( SELECT cr.cr_warehouse_sk AS warehouse_sk, CASE WHEN cr.cr_return_quantity <= 5 THEN 'SMALL' WHEN cr.cr_return_quantity BETWEEN 6 AND 20 THEN 'MEDIUM' ELSE 'LARGE' END AS qty_bin, COUNT(*) AS bin_return_cnt, SUM(cr.cr_net_loss) AS bin_net_loss FROM catalog_returns cr GROUP BY cr.cr_warehouse_sk, CASE WHEN cr.cr_return_quantity <= 5 THEN 'SMALL' WHEN cr.cr_return_quantity BETWEEN 6 AND 20 THEN 'MEDIUM' ELSE 'LARGE' END ), returning_city_counts AS ( SELECT cr.cr_warehouse_sk AS warehouse_sk, COUNT(DISTINCT ca_ret.ca_city) AS distinct_returning_cities FROM catalog_returns cr JOIN customer_address ca_ret ON cr.cr_returning_addr_sk = ca_ret.ca_address_sk GROUP BY cr.cr_warehouse_sk ) SELECT w.w_warehouse_name, w.w_state, ws.total_net_loss, ws.total_ship_cost, ws.total_return_quantity, ws.avg_return_amount, ws.distinct_returning_addr_cnt, rcc.distinct_returning_cities, qb.qty_bin, qb.bin_return_cnt, qb.bin_net_loss, RANK() OVER (ORDER BY ws.total_net_loss DESC) AS warehouse_loss_rank, SUM(ws.total_net_loss) OVER (ORDER BY ws.total_net_loss DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_loss, COALESCE(qb.bin_net_loss / NULLIF(ws.total_net_loss, 0), 0) AS bin_loss_share FROM warehouse_stats ws JOIN warehouse w ON ws.warehouse_sk = w.w_warehouse_sk LEFT JOIN quantity_bins qb ON ws.warehouse_sk = qb.warehouse_sk LEFT JOIN returning_city_counts rcc ON ws.warehouse_sk = rcc.warehouse_sk ORDER BY warehouse_loss_rank, qb.qty_bin
